#!/usr/bin/env node
/**
 * Downloads Satoshi from Fontshare (Indian Type Foundry, free for commercial
 * use under the ITF Free Font License) and wires it into both apps:
 *
 *   mobile/assets/fonts/Satoshi-{Regular,Medium,Bold}.otf  + generated manifest
 *   web/public/fonts/Satoshi-Variable.woff2               + generated @font-face
 *
 * Until this runs, both apps use their fallback fonts. Run once, then commit
 * the generated files:  npm run fonts:satoshi
 */
import { mkdirSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { unzipSync } from 'fflate';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const url = process.env.SATOSHI_URL ?? 'https://api.fontshare.com/v2/fonts/download/satoshi';

const res = await fetch(url);
if (!res.ok) {
  console.error(`Could not download Satoshi (${res.status}). Download it manually from https://www.fontshare.com/fonts/satoshi and see docs/DESIGN.md.`);
  process.exit(1);
}
const files = unzipSync(new Uint8Array(await res.arrayBuffer()));
const find = (re) => Object.keys(files).find((name) => re.test(name) && !name.startsWith('__MACOSX'));

const mobileDir = join(root, 'mobile/assets/fonts');
const webDir = join(root, 'web/public/fonts');
mkdirSync(mobileDir, { recursive: true });
mkdirSync(webDir, { recursive: true });

const weights = { Regular: null, Medium: null, Bold: null };
for (const w of Object.keys(weights)) {
  const name = find(new RegExp(`(^|/)Satoshi-${w}\\.otf$`)) ?? find(new RegExp(`(^|/)Satoshi-${w}\\.ttf$`));
  if (!name) throw new Error(`Satoshi-${w} (otf/ttf) not found in the download`);
  const ext = name.slice(-3);
  writeFileSync(join(mobileDir, `Satoshi-${w}.${ext}`), files[name]);
  weights[w] = `Satoshi-${w}.${ext}`;
}
const variable = find(/(^|\/)Satoshi-Variable\.woff2$/);
if (!variable) throw new Error('Satoshi-Variable.woff2 not found in the download');
writeFileSync(join(webDir, 'Satoshi-Variable.woff2'), files[variable]);
const license = find(/licen[cs]e/i);
if (license) {
  writeFileSync(join(mobileDir, 'SATOSHI-LICENSE.txt'), files[license]);
  writeFileSync(join(webDir, 'SATOSHI-LICENSE.txt'), files[license]);
}

writeFileSync(
  join(root, 'mobile/src/theme/fonts.generated.ts'),
  `// Generated by scripts/fetch-satoshi.mjs — do not edit.
/* eslint-disable @typescript-eslint/no-require-imports */
export const SATOSHI_AVAILABLE = true;
export const fontAssets: Record<string, number> = {
${Object.entries(weights).map(([w, f]) => `  'Satoshi-${w}': require('../../assets/fonts/${f}'),`).join('\n')}
};
`,
);
writeFileSync(
  join(root, 'web/src/app/satoshi.css'),
  `/* Generated by scripts/fetch-satoshi.mjs — do not edit. Satoshi © Indian Type Foundry, ITF Free Font License. */
@font-face {
  font-family: 'Satoshi';
  src: url('/fonts/Satoshi-Variable.woff2') format('woff2');
  font-weight: 300 900;
  font-style: normal;
  font-display: swap;
}
`,
);
console.log('Satoshi installed for mobile and web. Commit mobile/assets/fonts, web/public/fonts and the two generated files.');
